FUNCTION_BLOCK FB_Compresor
VAR_INPUT
    pOilOk    : BOOL; // Presión de aceite correcta
    tempOk    : BOOL; // Temperatura correcta
    sinAlm    : BOOL; // Ausencia de alarmas
    btnMarcha : BOOL; // Botón de arranque
    btnParo   : BOOL; // Botón de detención
END_VAR

VAR_OUTPUT
    comp         : BOOL; // Comando de marcha del compresor
    causaBloqueo : INT;  // Indicador del permisivo faltante (0=OK, 1=Aceite, 2=Temp, 3=Alarma)
END_VAR

VAR
    tonOil      : TON;    // Temporizador para validar la presión de aceite
    rTrigMarcha : R_TRIG; // Detector de flanco de subida para el botón de marcha
    permisivos  : BOOL;   // Estado de todos los permisivos combinados
END_VAR

// 1. Evaluación del permisivo de aceite (3 segundos continuos)
tonOil(IN := pOilOk, PT := T#3S);

// 2. Detección de la pulsación de marcha (transición FALSE -> TRUE)
rTrigMarcha(CLK := btnMarcha);

// 3. Lógica de diagnóstico de bloqueo (prioridad al número menor)
IF NOT tonOil.Q THEN
    causaBloqueo := 1; // Falta presión de aceite (o no ha cumplido el tiempo)
ELSIF NOT tempOk THEN
    causaBloqueo := 2; // Falta temperatura correcta
ELSIF NOT sinAlm THEN
    causaBloqueo := 3; // Alarma activa
ELSE
    causaBloqueo := 0; // Todos los permisivos se cumplen
END_IF;

// 4. Agrupación de permisivos
permisivos := (causaBloqueo = 0);

// 5. Lógica de control de marcha/paro del compresor
// El paro y la pérdida de permisivos tienen prioridad absoluta
IF btnParo OR NOT permisivos THEN
    comp := FALSE;
// Solo arranca con el flanco de subida si los permisivos están listos
ELSIF rTrigMarcha.Q AND permisivos THEN
    comp := TRUE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compresor
VAR
    // Entradas
    pOilOk : BOOL;       // Presión de aceite correcta
    tempOk : BOOL;       // Temperatura correcta
    sinAlm : BOOL;       // Sin alarmas
    btnMarcha : BOOL;    // Botón de marcha
    btnParo : BOOL;      // Botón de paro

    // Salidas
    comp : BOOL;         // Estado del compresor
    causaBloqueo : INT;  // Causa de bloqueo

    // Variables internas
    pOilOkTimer : TON;   // Temporizador para presión de aceite
    marchaLatch : BOOL;  // Latch para mantener el compresor en marcha
END_VAR

// Inicialización del temporizador
pOilOkTimer(IN := pOilOk, PT := T#3S);

// Lógica de causa de bloqueo
IF NOT pOilOkTimer.Q THEN
    causaBloqueo := 1; // Falta presión de aceite
ELSIF NOT tempOk THEN
    causaBloqueo := 2; // Falta temperatura correcta
ELSIF NOT sinAlm THEN
    causaBloqueo := 3; // Hay alarmas activas
ELSE
    causaBloqueo := 0; // No hay bloqueos
END_IF;

// Lógica de arranque y paro del compresor
IF btnParo THEN
    marchaLatch := FALSE; // Parar el compresor
ELSIF btnMarcha AND NOT marchaLatch AND (causaBloqueo = 0) THEN
    marchaLatch := TRUE; // Arrancar el compresor
END_IF;

// Actualizar el estado del compresor
comp := marchaLatch AND (causaBloqueo = 0);

FUNCTION_BLOCK FB_Compresor
VAR_INPUT
    pOilOk : BOOL; // Presión de aceite correcta
    tempOk : BOOL; // Temperatura correcta
    sinAlm : BOOL; // Ausencia de alarmas
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL; // Botón de paro
END_VAR

VAR_OUTPUT
    comp : BOOL; // Salida del compresor
    causaBloqueo : INT; // Causa del bloqueo
END_VAR

VAR
    timerOilOk : TON; // Temporizador para la presión de aceite
    marchaAnterior : BOOL; // Estado anterior del botón de marcha
    paroAnterior : BOOL; // Estado anterior del botón de paro
    permisivoCumplido : BOOL; // Indica si todos los permisivos están cumplidos
    estadoMarcha : BOOL; // Estado actual del compresor
END_VAR

// Inicialización del temporizador
IF NOT timerOilOk.Q THEN
    timerOilOk(IN := FALSE, PT := T#3S);
END_IF;

// Actualización de estados anteriores
marchaAnterior := btnMarcha;
paroAnterior := btnParo;

// Lógica de paro
IF btnParo AND NOT paroAnterior THEN
    comp := FALSE;
    estadoMarcha := FALSE;
END_IF;

// Lógica de arranque
IF btnMarcha AND NOT marchaAnterior THEN
    timerOilOk(IN := pOilOk);
    permisivoCumplido := pOilOk AND tempOk AND sinAlm;
    IF permisivoCumplido THEN
        comp := TRUE;
        estadoMarcha := TRUE;
    END_IF;
END_IF;

// Mantener el compresor en marcha si ya está arrancado
IF estadoMarcha THEN
    comp := TRUE;
ELSE
    comp := FALSE;
END_IF;

// Determinar la causa del bloqueo
IF NOT pOilOk THEN
    causaBloqueo := 1;
ELSIF NOT tempOk THEN
    causaBloqueo := 2;
ELSIF NOT sinAlm THEN
    causaBloqueo := 3;
ELSE
    causaBloqueo := 0;
END_IF;

// Reiniciar el temporizador si la presión de aceite se pierde
IF NOT pOilOk THEN
    timerOilOk(IN := FALSE);
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compresor
VAR_INPUT
    pOilOk : BOOL; // Presión de aceite correcta
    tempOk : BOOL; // Temperatura correcta
    sinAlm : BOOL; // Ausencia de alarmas
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL; // Botón de paro
END_VAR

VAR_OUTPUT
    comp : BOOL; // Salida del compresor
    causaBloqueo : INT; // Causa de bloqueo
END_VAR

VAR
    timerOilOk : TON; // Temporizador para presión de aceite
    estadoMarcha : BOOL; // Estado de marcha del compresor
    lastBtnMarcha : BOOL; // Estado anterior del botón de marcha
    lastBtnParo : BOOL; // Estado anterior del botón de paro
END_VAR

// Inicialización
IF NOT estadoMarcha THEN
    comp := FALSE;
    causaBloqueo := 0;
END_IF

// Actualización de estados de botones
IF btnMarcha <> lastBtnMarcha THEN
    lastBtnMarcha := btnMarcha;
END_IF

IF btnParo <> lastBtnParo THEN
    lastBtnParo := btnParo;
END_IF

// Paro del compresor por botón de paro o pérdida de permisivos
IF btnParo OR (estadoMarcha AND (NOT pOilOk OR NOT tempOk OR NOT sinAlm)) THEN
    comp := FALSE;
    estadoMarcha := FALSE;
END_IF

// Inicio del compresor por botón de marcha
IF NOT estadoMarcha AND btnMarcha AND pOilOk AND tempOk AND sinAlm THEN
    comp := TRUE;
    estadoMarcha := TRUE;
END_IF

// Control de la causa de bloqueo
IF NOT pOilOk THEN
    causaBloqueo := 1;
ELSIF NOT tempOk THEN
    causaBloqueo := 2;
ELSIF NOT sinAlm THEN
    causaBloqueo := 3;
ELSE
    causaBloqueo := 0;
END_IF

// Temporizador para presión de aceite
timerOilOk(IN := pOilOk, PT := T#3S);
IF timerOilOk.Q THEN
    // Presión de aceite correcta durante 3 segundos
    // (No se necesita acción adicional aquí)
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compresor
VAR_INPUT
    pOilOk : BOOL; // Presión de aceite correcta
    tempOk : BOOL; // Temperatura correcta
    sinAlm : BOOL; // Ausencia de alarmas
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL; // Botón de paro
END_VAR

VAR_OUTPUT
    comp : BOOL; // Salida del compresor
    causaBloqueo : INT; // Causa de bloqueo
END_VAR

VAR
    timerOilOk : TON; // Temporizador para presión de aceite
    marchaAnterior : BOOL; // Estado anterior del botón de marcha
    paroAnterior : BOOL; // Estado anterior del botón de paro
    permisivoCumplido : BOOL; // Indica si se cumplen todos los permisivos
END_VAR

// Inicialización del temporizador
IF NOT timerOilOk.Q THEN
    timerOilOk(IN := FALSE, PT := T#3S);
END_IF

// Detectar transición de botón de marcha
IF btnMarcha AND NOT marchaAnterior THEN
    timerOilOk(IN := pOilOk);
END_IF

// Detectar transición de botón de paro
IF btnParo AND NOT paroAnterior THEN
    comp := FALSE;
END_IF

// Actualizar estado de botones
marchaAnterior := btnMarcha;
paroAnterior := btnParo;

// Verificar permisivos
permisivoCumplido := pOilOk AND tempOk AND sinAlm AND timerOilOk.Q;

// Determinar causa de bloqueo
IF NOT pOilOk THEN
    causaBloqueo := 1;
ELSIF NOT tempOk THEN
    causaBloqueo := 2;
ELSIF NOT sinAlm THEN
    causaBloqueo := 3;
ELSE
    causaBloqueo := 0;
END_IF

// Control de arranque y paro
IF btnParo THEN
    comp := FALSE;
ELSEIF btnMarcha AND permisivoCumplido THEN
    comp := TRUE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compresor
VAR_INPUT
    pOilOk    : BOOL; // Presión de aceite correcta
    tempOk    : BOOL; // Temperatura correcta
    sinAlm    : BOOL; // Ausencia de alarmas
    btnMarcha : BOOL; // Botón de arranque
    btnParo   : BOOL; // Botón de detención
END_VAR

VAR_OUTPUT
    comp         : BOOL; // Comando de marcha del compresor
    causaBloqueo : INT;  // Código del permisivo faltante (0=Ninguno, 1=Aceite, 2=Temp, 3=Alarma)
END_VAR

VAR
    timerOil   : TON;    // Temporizador para validar la presión de aceite
    edgeMarcha : R_TRIG; // Detector de flanco de subida para el botón de marcha
    permisivos : BOOL;   // Bandera interna de todos los permisivos OK
END_VAR

// 1. Evaluación del tiempo de la presión de aceite (3 segundos continuos)
timerOil(IN := pOilOk, PT := T#3S);

// 2. Determinación de la causa de bloqueo (Prioridad al número menor)
IF NOT timerOil.Q THEN
    causaBloqueo := 1; // Falta presión de aceite o no ha transcurrido el tiempo
ELSIF NOT tempOk THEN
    causaBloqueo := 2; // Falta temperatura correcta
ELSIF NOT sinAlm THEN
    causaBloqueo := 3; // Presencia de alarma
ELSE
    causaBloqueo := 0; // Todos los permisivos se cumplen
END_IF;

// 3. Consolidación de permisivos
permisivos := (causaBloqueo = 0);

// 4. Detección de la pulsación de marcha (transición FALSE a TRUE)
edgeMarcha(CLK := btnMarcha);

// 5. Lógica de arranque y paro del compresor
// El paro y la pérdida de permisivos tienen prioridad absoluta
IF btnParo OR NOT permisivos THEN
    comp := FALSE;
// Solo arranca con un nuevo flanco de subida si los permisivos están listos
ELSIF edgeMarcha.Q AND permisivos THEN
    comp := TRUE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compresor
VAR_INPUT
    pOilOk    : BOOL; // Presión de aceite correcta
    tempOk    : BOOL; // Temperatura correcta
    sinAlm    : BOOL; // Ausencia de alarmas
    btnMarcha : BOOL; // Botón de arranque
    btnParo   : BOOL; // Botón de parada
END_VAR

VAR_OUTPUT
    comp         : BOOL; // Comando de arranque del compresor
    causaBloqueo : INT;  // Código del permisivo faltante (0=Ninguno, 1=Aceite, 2=Temp, 3=Alarma)
END_VAR

VAR
    tonOil     : TON;    // Temporizador para validar la presión de aceite
    trigMarcha : R_TRIG; // Detector de flanco de subida para el arranque
    permisivos : BOOL;   // Marca interna de todos los permisivos cumplidos
END_VAR

// 1. Temporizador: requiere 3 segundos continuos de pOilOk
tonOil(IN := pOilOk, PT := T#3S);

// 2. Lógica de diagnóstico de bloqueo (prioridad al número menor mediante IF-ELSIF)
IF NOT tonOil.Q THEN
    causaBloqueo := 1; // Falla 1: Presión de aceite no establecida
ELSIF NOT tempOk THEN
    causaBloqueo := 2; // Falla 2: Temperatura incorrecta
ELSIF NOT sinAlm THEN
    causaBloqueo := 3; // Falla 3: Alarma activa
ELSE
    causaBloqueo := 0; // Sin fallas: Todos los permisivos OK
END_IF;

// 3. Evaluación global de permisivos
permisivos := (causaBloqueo = 0);

// 4. Detección de pulsación (transición FALSE a TRUE) del botón de marcha
trigMarcha(CLK := btnMarcha);

// 5. Lógica de control de marcha/paro del compresor
IF btnParo OR NOT permisivos THEN
    // El paro y la pérdida de permisivos tienen prioridad y detienen el equipo
    comp := FALSE;
ELSIF trigMarcha.Q AND permisivos THEN
    // Solo arranca con un nuevo flanco de subida si los permisivos están listos
    comp := TRUE;
END_IF;

END_FUNCTION_BLOCK
